; Reads keyboard column 0 and fire on port 2. F1 or fire starts a game, F3 changes 1/2 players, F5 goes to the title, F7 toggles JOYSTICK/KEYBOARD, DEL toggles the samples. Returns A = $80 to start. Called each frame by bout_loop.
read_title_keys
        lda #$ff
        sta CIADDRA
        lda #$00
        sta CIADDRB
        lda #$fe
        sta CIAPRA
        lda CIAPRB
        cmp last_key_row                ; Acts only when the row value changes.
        beq title_keys_fire
        sta last_key_row
        cmp #$ef                        ; F1
        beq title_key_f1
        cmp #$df                        ; F3
        beq title_key_f3
        cmp #$bf                        ; F5
        beq title_key_f5
        cmp #$f7                        ; F7
        beq title_key_f7
        cmp #$fe                        ; INST/DEL, new in v2.
        beq title_key_del
title_keys_fire
        lda in_game
        bne title_keys_none
        lda CIAPRA
        and #$10
        bne title_keys_none
        lda #$80
        rts
title_keys_none
        lda #$00
        rts
title_key_f1
        lda in_game
        bne title_keys_fire
        lda #$80
        rts
title_key_f3
        lda in_game
        bne title_f3_done
        inc two_player_mode
        lda two_player_mode
        cmp #$02
        bne title_f3_show
        lda #$00
        sta two_player_mode
title_f3_show
        jsr show_mode_text
        jsr high_score_show
title_f3_done
        lda #$00
        rts
title_key_f7
        lda in_game
        bne title_f7_done
        lda keyboard_control            ; New in v2: 0 joystick, 1 keyboard for the human fighters.
        eor #$01
        sta keyboard_control
        jsr show_control_text
title_f7_done
        lda #$00                        ; The v1 F7 code: LDA #0, RTS.
        rts
title_key_f5
        jmp title_main_loop             ; F5 works also during a game; the stack is not reset.
title_key_del
        lda in_game
        bne title_del_done
        lda samples_off                 ; New in v2: samples_off; sfx_sample_start ($3186) starts no sample when it is not 0.
        eor #$01
        sta samples_off
title_del_done
        lda #$00
        rts
; Title loop: high score, mode text, control text and the demo again and again. A start key starts the game of two_player_mode; after a 1P game the high score table follows. Entered from cold_start and F5.
title_main_loop
        lda #$00
        sta two_player_mode
title_demo_loop
        jsr high_score_show
        jsr show_mode_text
        jsr show_control_text           ; New in v2: JOYSTICK or KEYBOARD at $cc97.
        lda #$00
        sta in_game
        ldx #$09
        jsr score_clear
        ldx #$19
        jsr score_clear
        jsr demo_play
        bpl title_demo_loop             ; N clear: the demo ended without a start key.
        lda two_player_mode
        beq title_start_1p
title_test_2p
        cmp #$01
        beq title_start_2p
title_bad_mode
; not executed $1f09-$1f09
        rts                             ; No mode 2 or more exists, as in v1.
title_start_1p
        jsr game_one_player
        jsr hs_table_update             ; New in v2: the top-5 high score table and name entry; v1 started a new game here when fire was held.
        jsr hs_clear_panel              ; Clears the panel after the table.
        jmp title_demo_loop
title_start_2p
        jsr game_two_players
        bmi title_start_2p
        jmp title_demo_loop
; Clears the scene bitmap $e640-$f53f (15 pages) with 0 through a self-modified STA. Called by scene_draw_if_new. v1 filled the colour RAM and screen of rows 5-16 with $33 here.
